[
  {
    "name": "sys_id",
    "type": "string",
    "description": "Unique fictional 32-character lowercase hexadecimal ID."
  },
  {
    "name": "number",
    "type": "string",
    "description": "Unique ServiceNow-style incident number such as INC0012345."
  },
  {
    "name": "short_description",
    "type": "string",
    "description": "Short user-reported issue summary; vary clarity and terminology."
  },
  {
    "name": "description",
    "type": "string",
    "description": "Full issue narrative with realistic symptoms, context, and occasional missing details."
  },
  {
    "name": "state",
    "type": "string",
    "description": "One of New, In Progress, On Hold, Resolved, Closed, or Canceled."
  },
  {
    "name": "impact",
    "type": "integer",
    "description": "1=High, 2=Medium, 3=Low."
  },
  {
    "name": "urgency",
    "type": "integer",
    "description": "1=High, 2=Medium, 3=Low."
  },
  {
    "name": "priority",
    "type": "integer",
    "description": "ServiceNow priority derived consistently from impact and urgency; 1 is most critical and 5 is lowest."
