    "description": "ISO 8601 timestamp."
  },
  {
    "name": "updated_at",
    "type": "datetime",
    "description": "ISO 8601 timestamp at or after opened_at."
  },
  {
    "name": "close_code",
    "type": "string|null",
    "description": "Null unless resolved or closed; otherwise a plausible close code."
  },
  {
    "name": "resolution_notes",
    "type": "string|null",
    "description": "Null for active tickets; plausible resolution for resolved or closed tickets."
  },
